// the registry calls RegisterAll() on first use once this header is part of the program
struct HookInstaller {
    HookInstaller() { ::imb::detail::MotionPresetsHook() = &RegisterAll; }
};
// static, not inline, so it builds as C++14. each TU stores the same pointer
static HookInstaller hook_installer;
